import {materialIcon as mi} from './material-icons.js';
import {currentLocale} from './locale.js';
import {escape,money,button,route,imageUrl} from './ui.js';
export const orderStatuses={PENDING_SHIPMENT:'待出貨',SHIPPED:'已出貨',DELIVERY_ASSIGNING:'配送安排中',DELIVERY_ASSIGNED:'已安排配送',DELIVERY_EN_ROUTE_TO_PICKUP:'前往取件中',DELIVERY_PICKUP_DELAYED:'取件延遲',DELIVERY_PICKED_UP:'已取件',DELIVERY_EN_ROUTE_TO_BUYER:'配送途中',DELIVERY_DELIVERY_DELAYED:'配送延遲',DELIVERY_FAILED:'配送失敗',DELIVERY_RETURNING:'配送退回中',DELIVERY_COMPLETED:'已送達',PURCHASE_IN_PROGRESS:'採購處理中',PROOF_SUBMITTED:'待確認交付證明',BUYER_CONFIRMED:'買家已確認',RETURN_REQUESTED:'退貨申請中',RETURN_REJECTED:'退貨申請被拒絕',RETURN_APPROVED:'退貨已核准',RETURN_SHIPPED_BY_BUYER:'買家已寄回',RETURN_SHIPPING_DELAYED:'退貨物流延遲',RETURN_RECEIVED:'退貨已收件',REFUND_NO_RETURN_OFFERED:'待回應免退貨退款方案',REFUND_NO_RETURN_PARTIAL_OFFERED:'待回應部分退款方案',DISPUTE_OPENED:'爭議處理中',DISPUTE_RESPONDED:'賣家已回應爭議',CANCELLED_BY_BUYER:'買家已取消',CANCELLED_BY_SELLER:'賣家已取消',CANCELLED_BY_PLATFORM:'平台已取消',REFUNDED:'已退款',DISPUTE_RESOLVED:'爭議已結案',COMPLETED_FINAL:'訂單已完成'};
export const orderStatus=value=>nativeOrderText('orderStatus'+(value==='DELIVERY_DELIVERY_DELAYED'?'DeliveryDelayed':String(value||'').toLowerCase().replace(/(^|_)([a-z])/g,(_,a,b)=>b.toUpperCase())))||nativeOrderText('orderUnknownStatus');
export const settlementCurrency=value=>{const s=String(value||'').trim().toUpperCase();return !s||['TWD','THB'].includes(s)?'USDT':s;};
export const orderDate=value=>{const d=new Date(value);return value&&Number.isFinite(d.getTime())?d.getFullYear()+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'):'—';};
export function orderRelativeDate(value,now=Date.now()){
 const d=new Date(value);if(!value||!Number.isFinite(d.getTime()))return'—';
 const seconds=Math.floor((now-d.getTime())/1000),en=currentLocale().startsWith('en');
 if(seconds<0)return orderDate(value);if(seconds<60)return en?'Just now':'剛剛';if(seconds<3600)return Math.floor(seconds/60)+(en?' minutes ago':' 分鐘前');if(seconds<86400)return Math.floor(seconds/3600)+(en?' hours ago':' 小時前');const days=Math.floor(seconds/86400);if(days===1)return en?'Yesterday':'昨天';if(days<7)return days+(en?' days ago':' 天前');return orderDate(value).slice(0,10);
}
export const returnReasons={NOT_AS_DESCRIBED:'商品與描述不符',DAMAGED_OR_DEFECTIVE:'商品損壞或有瑕疵',WRONG_OR_MISSING_ITEM:'品項錯誤或短缺',NOT_DELIVERED_OR_UNCLAIMABLE:'未收到或無法領取',OTHER:'其他原因'};
export function evidenceImages(values){return [...(values||[])].map(imageUrl).filter(Boolean).map(url=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer"><img src="${escape(url)}" alt="${escape(nativeOrderText('disputeEvidenceImage'))}" loading="lazy"></a>`).join('');}
export function receiptPanel(receipt,{onOrdersPage=false}={}){const ids=receipt.orderIds;return `<section class="panel order-recovery-receipt"><p>${escape(nativeOrderText('checkoutRecoveryFound',{orders:ids.slice(0,5).join(', ')}))}</p>${ids.map(id=>`<p><a class="secondary" href="${route('/orders/'+encodeURIComponent(id))}">${escape(nativeOrderText('orderDetails'))} ${escape(id)}</a></p>`).join('')}${button(nativeOrderText(onOrdersPage?'checkoutRecoveryAcknowledge':'checkoutRecoveryOrders'),'ack-receipt','secondary',`data-receipt-id="${escape(receipt.receiptId)}"`)}</section>`;}

export function returnDetails(r){if(!r)return '';const t=nativeOrderText;return `<section class="panel"><h2>${escape(t('returnInformation'))}</h2><p>${escape(nativeReturnReason(r.reason))}</p><p class="description">${escape(r.description||'')}</p><p>${escape(t('applicationTime'))}：${escape(orderDate(r.requestedAt))}</p>${r.sellerReply?`<h3>${escape(t('sellerReply'))}</h3><p class="description">${escape(r.sellerReply)}</p>`:''}${r.returnRecipientName||r.returnAddress?`<h3>${escape(t('sellerReturnRecipientInfo'))}</h3><p>${escape(r.returnRecipientName||'')} ${escape(r.returnRecipientPhone||'')}</p><p class="description">${escape(r.returnAddress||'')}</p>`:''}${r.returnDeadline?`<p class="${r.returnOverdue?'form-errors':'muted'}">${escape(commerceText('returnDeadline'))} ${escape(orderDate(r.returnDeadline))}</p>`:''}${r.trackingNumber?`<p>${escape(t('returnShippingInformation'))}：${escape(r.shippingCompany||'')} · ${escape(r.trackingNumber)}</p>`:''}<div class="order-evidence">${evidenceImages(r.imageUrls)}</div></section>`;}
export function disputeDetails(d){if(!d)return '';const t=nativeOrderText,status=t({PENDING:'disputeStatusPending',COMPLETED:'disputeStatusCompleted',REJECTED:'disputeStatusRejected'}[d.status]||'disputeStatusPending');return `<section class="panel"><h2>${escape(t('disputeInfo'))} · ${escape(status)}</h2><p class="description">${escape(d.description||'')}</p><div class="order-evidence">${evidenceImages(d.imageUrls)}</div>${d.sellerReply?`<h3>${escape(t('sellerReply'))}</h3><p class="description">${escape(d.sellerReply)}</p><div class="order-evidence">${evidenceImages(d.sellerReplyImageUrls)}</div>`:''}${d.adminComment?`<h3>${escape(t('disputePlatformNote'))}</h3><p class="description">${escape(d.adminComment)}</p>`:''}<p class="muted">${escape(t('createdAt'))}：${escape(orderDate(d.createdAt))}</p>${d.resolvedAt?`<p class="muted">${escape(t('resolvedAt'))}：${escape(orderDate(d.resolvedAt))}</p>`:''}</section>`;}

