export function nativeOrderText(key,args={}){return String(nativeOrderCopies[currentLocale()]?.[key]||'').replace(/\{(\w+)\}/g,(match,name)=>Object.hasOwn(args,name)?String(args[name]):match);}
export const orderTabStatuses=[[],['PENDING_SHIPMENT'],['SHIPPED'],['DELIVERY_COMPLETED'],['RETURN_REQUESTED','RETURN_REJECTED','RETURN_APPROVED','RETURN_SHIPPED_BY_BUYER','RETURN_SHIPPING_DELAYED','RETURN_RECEIVED','REFUND_NO_RETURN_OFFERED','REFUND_NO_RETURN_PARTIAL_OFFERED','REFUNDED','DISPUTE_OPENED','DISPUTE_RESPONDED','DISPUTE_RESOLVED'],['CANCELLED_BY_BUYER']];
export function nativeOrderTone(status){
 if(['DELIVERY_FAILED','DELIVERY_RETURNING','CANCELLED_BY_BUYER','CANCELLED_BY_SELLER','CANCELLED_BY_PLATFORM','RETURN_REJECTED','DISPUTE_OPENED','DISPUTE_RESOLVED'].includes(status))return'error';
 if(['DELIVERY_COMPLETED','COMPLETED_FINAL','BUYER_CONFIRMED'].includes(status))return'tertiary';
 if(/^RETURN_|^REFUND_/.test(status)||status==='REFUNDED'||status==='PROOF_SUBMITTED')return'secondary';
 if(status==='DISPUTE_RESPONDED')return'muted';return Object.hasOwn(orderStatuses,status)?'primary':'muted';
}
export const orderCardStatus=status=>nativeOrderText({PENDING_SHIPMENT:'pendingShipment',SHIPPED:'shipped',COMPLETED_FINAL:'completed'}[status])||orderStatus(status);
export function orderCard(o,{withActions=false}={}){const items=Array.isArray(o.orderItems)&&o.orderItems.length?o.orderItems:null,total=items?items.reduce((n,i)=>n+Number(i.quantity??1),0):(o.itemCount>0?o.itemCount:o.quantity),cover=imageUrl(items?.[0]?.productImage||items?.[0]?.imageUrl||o.orderCoverImage||o.product?.imageUrls?.[0]),summary=items?items.map(i=>(i.productTitle||i.title||'')+(i.selectedSku?' · '+i.selectedSku:'')+' × '+(i.quantity??1)).join(' / '):o.orderTitle||o.product?.localizedTitle||o.product?.title||nativeOrderText('orderItems');return `<article class="order-native-card"><a class="order-native-card-link" href="${route('/orders/'+encodeURIComponent(o.id))}" aria-label="${escape(nativeOrderText('viewOrder',{orderId:o.id}))}"><div class="order-native-card-top"><div><strong>${escape(nativeOrderText('orderNumber'))} #${escape(o.id)}</strong><time>${escape(orderDate(o.createdAt))}</time></div><span class="order-native-status" data-tone="${nativeOrderTone(o.status)}">${escape(orderCardStatus(o.status))}</span></div><div class="order-native-card-body">${cover?`<img src="${escape(cover)}" alt="" loading="lazy">`:''}<div><h3>${escape(summary)}</h3><p class="order-native-price">${money(o.orderAmount)} <small>${escape(settlementCurrency(o.currency))}</small></p><div class="order-native-meta"><span>${mi('storefront_outlined')}${escape(o.store?.name||nativeOrderText('storeNumber',{sellerId:o.sellerId}))}</span><span>${mi('inventory_2_outlined')}${escape(nativeOrderText('quantity'))} ${escape(total)}</span></div></div></div></a>${withActions?orderCardActions(o):''}</article>`;}

export function nativeReturnReason(value){const keys={NOT_AS_DESCRIBED:'returnRecordReasonNotAsDescribed',DAMAGED_OR_DEFECTIVE:'returnRecordReasonDamagedOrDefective',WRONG_OR_MISSING_ITEM:'returnRecordReasonWrongOrMissingItem',NOT_DELIVERED_OR_UNCLAIMABLE:'returnRecordReasonNotDeliveredOrUnclaimable',OTHER:'returnRecordReasonOther'};return nativeOrderText(keys[value]||'returnReasonUnknown');}

export const nativeOrderStatusKeys={"PENDING_SHIPMENT":"orderStatusPendingShipment","SHIPPED":"orderStatusShipped","DELIVERY_ASSIGNING":"orderProgressStatusDelivering","DELIVERY_ASSIGNED":"orderProgressStatusDelivering","DELIVERY_EN_ROUTE_TO_PICKUP":"orderProgressStatusDelivering","DELIVERY_PICKUP_DELAYED":"orderProgressStatusDelivering","DELIVERY_PICKED_UP":"orderProgressStatusDelivering","DELIVERY_EN_ROUTE_TO_BUYER":"orderProgressStatusDelivering","DELIVERY_DELIVERY_DELAYED":"orderProgressStatusDelivering","DELIVERY_FAILED":"orderProgressStatusDeliveryFailed","DELIVERY_RETURNING":"orderProgressStatusReturning","DELIVERY_COMPLETED":"orderProgressStatusDelivered","COMPLETED_FINAL":"orderProgressStatusCompleted","CANCELLED_BY_BUYER":"orderProgressStatusCancelled","CANCELLED_BY_PLATFORM":"orderProgressStatusCancelled","CANCELLED_BY_SELLER":"orderProgressStatusCancelled","RETURN_REQUESTED":"orderProgressStatusReturnRequested","RETURN_REJECTED":"orderProgressStatusReturnRejected","RETURN_APPROVED":"orderProgressStatusReturnApproved","RETURN_SHIPPED_BY_BUYER":"returnInProgress","RETURN_SHIPPING_DELAYED":"returnInProgress","RETURN_RECEIVED":"orderProgressStatusReturnReceived","REFUND_NO_RETURN_OFFERED":"orderProgressStatusRefundProposal","REFUND_NO_RETURN_PARTIAL_OFFERED":"orderProgressStatusRefundProposal","REFUNDED":"orderProgressStatusRefunded","DISPUTE_OPENED":"disputed","DISPUTE_RESPONDED":"disputed","DISPUTE_RESOLVED":"disputed","PURCHASE_IN_PROGRESS":"orderStatusPurchaseInProgress","PROOF_SUBMITTED":"orderStatusProofSubmitted","BUYER_CONFIRMED":"orderProgressStatusCompleted","unknownDefaultOpenApi":"orderUnknownStatus"};
export const nativeOrderStatus=value=>nativeOrderText(nativeOrderStatusKeys[value]||'orderUnknownStatus');

